// @vitest-environment jsdom
// site-day-model.test.tsx — the Operations day as a metrics view model.
//
// Every case of daily-operations.test.tsx, asserted on the model's strings
// instead of the component's markup, with the same hand-built days. Then a
// parity sweep renders the legacy component and builds the model from the
// same days (hand-built and generated by the fixture provider) and requires
// the same visible text. Then the strict parse: the model against a view
// declaring SITE_DAY_KEYS and the metering.site-day@1 ext.

import { describe, it, expect, vi } from "vitest";
import { renderToStaticMarkup } from "react-dom/server";
import React from "react";

vi.mock("@/components/format/locale-context", () => ({
  useLocale: () => ({ locale: "en-UG", currency: "UGX" }),
  LocaleProvider: ({ children }: { children: React.ReactNode }) => children,
}));

import { DailyOperations } from "@/components/operations/daily-operations";
import { createFmt } from "@/lib/gui/fmt";
import { strictParseModel } from "@/lib/gui/host/server/parse";
import { strictProblems } from "@/lib/gui/host/server/contribution-schema";
import type { ViewDef } from "@/lib/gui/surface";
import { addDaysToDateKey } from "@/lib/timezone/day-key";
import { generateSiteSamples, siteScenario, SITE_FIXTURE_SEED, type SiteScenario } from "../../fixture/site-samples";
import { computeSiteDay, type SiteDayOperations } from "../../site-operations";
import type { SiteSources } from "../../types";
import { SiteDayExt } from "../site-day-ext";
import { buildNoSiteDevicesModel, buildSiteDayModel, SITE_DAY_EXT_SCHEMA, SITE_DAY_KEYS } from "../site-day-model";

// ── Fixtures (as in daily-operations.test.tsx) ───────────────────────────────

const LOCALE = "en-UG";
const fmt = createFmt({ locale: LOCALE });
const MG = { id: "00000000-0000-4000-8000-0000000000a1", name: "North site" };
const OPS = `/microgrids/${MG.id}/operations`;
const HOUR = 3_600_000;
const MIN = 60_000;
const DAY_START = Date.parse("2026-11-04T21:00:00Z");
const at = (hour: number, minute = 0) => DAY_START + hour * HOUR + minute * MIN;

function makeDay(overrides: Partial<SiteDayOperations> = {}): SiteDayOperations {
  return {
    date: "2026-11-05",
    timezone: "Africa/Kampala",
    dayStartMs: DAY_START,
    dayEndMs: at(24),
    readUntilMs: at(24),
    resolutionMinutes: 15,
    eveningStartMs: at(18),
    hourMarks: [0, 3, 6, 9, 12, 15, 18, 21, 24].map((hour) => ({ hour, atMs: at(hour) })),
    sources: { battery: true, gridMeter: true, load: true, pv: true, houses: true, houseMetersUnreadable: 0 },
    solarKwh: 12.34,
    solarEstimated: false,
    eveningDischargeKwh: 4.56,
    housesEveningKwh: 3.21,
    housesEveningMetersMissing: 0,
    cuts: [
      { startMs: at(2), endMs: at(4, 30) },
      { startMs: at(13), endMs: at(14, 40) },
    ],
    cutMinutes: 250,
    lowestSoc: { pct: 12.4, atMs: at(5, 30), duringCut: true },
    socAtCheckHour: 63.6,
    dark: [{ startMs: at(23), endMs: at(24) }],
    darkMinutes: 60,
    darkInferredMinutes: 0,
    noDataMinutes: 0,
    lightsOnPct: (100 * (1440 - 60)) / 1440,
    soc: [
      { atMs: at(0), pct: 80 },
      { atMs: at(0, 15), pct: 78 },
      { atMs: at(0, 30), pct: null },
      { atMs: at(0, 45), pct: 70 },
      { atMs: at(1), pct: 69 },
    ],
    evening: [
      { startMs: at(18), endMs: at(21), supply: "battery" },
      { startMs: at(21), endMs: at(22), supply: "battery_and_grid" },
      { startMs: at(22), endMs: at(23), supply: "grid" },
      { startMs: at(23), endMs: at(24), supply: "dark" },
    ],
    eveningHours: { battery: 3, battery_and_grid: 1, grid: 1, dark: 1, no_data: 0 },
    ...overrides,
  };
}

const NULL_DAY: Partial<SiteDayOperations> = {
  sources: { battery: false, gridMeter: false, load: false, pv: false, houses: false, houseMetersUnreadable: 0 },
  solarKwh: null,
  eveningDischargeKwh: null,
  housesEveningKwh: null,
  cuts: null,
  cutMinutes: null,
  lowestSoc: null,
  socAtCheckHour: null,
  dark: [],
  darkMinutes: 0,
  lightsOnPct: null,
  soc: [],
};
const BEFORE_EVENING: Partial<SiteDayOperations> = {
  readUntilMs: at(14, 15),
  evening: [],
  eveningHours: { battery: 0, battery_and_grid: 0, grid: 0, dark: 0, no_data: 0 },
};

const build = (day: SiteDayOperations, today = "2026-11-06") =>
  buildSiteDayModel(day, { microgrid: MG, today, locale: LOCALE, fmt });
const tile = (day: SiteDayOperations, key: string) => {
  const found = build(day).body.tiles.find((t) => t.key === key);
  if (!found) throw new Error(`No tile ${key}`);
  return found;
};
const text = (day: SiteDayOperations, key: string) => tile(day, key).value.text;
const hint = (day: SiteDayOperations, key: string) => tile(day, key).hint;
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const ext = (day: SiteDayOperations) => build(day).ext!.data as any;

// ── The legacy cases ────────────────────────────────────────────────────────

describe("buildSiteDayModel", () => {
  it("gives solar and what the houses used in the evening, with the battery's share", () => {
    expect(text(makeDay(), "solar")).toBe("12.3 kWh");
    expect(hint(makeDay(), "solar")).toBe("Solar meter");
    expect(text(makeDay(), "houses-evening")).toBe("3.2 kWh");
    expect(hint(makeDay(), "houses-evening")).toBe("Battery supplied 4.6 kWh");
    expect(text(makeDay(), "battery-evening")).toBe("4.6 kWh");
    expect(hint(makeDay(), "battery-evening")).toBeUndefined();
  });

  it("notes house meters left out for want of data", () => {
    expect(hint(makeDay({ housesEveningMetersMissing: 1 }), "houses-evening")).toBe(
      "Battery supplied 4.6 kWh · 1 meter without data",
    );
    expect(hint(makeDay({ housesEveningMetersMissing: 2 }), "houses-evening")).toContain("2 meters without data");
    const none = makeDay({ housesEveningKwh: null, housesEveningMetersMissing: 3 });
    expect(tile(none, "houses-evening").value).toEqual({ t: "empty", text: "—" });
    expect(hint(none, "houses-evening")).toBe("Battery supplied 4.6 kWh · 3 meters without data");
  });

  it("says household meters are needed when there are none", () => {
    const day = makeDay({ sources: { ...makeDay().sources, houses: false }, housesEveningKwh: null });
    expect(text(day, "houses-evening")).toBe("—");
    expect(hint(day, "houses-evening")).toBe("Needs household meters · Battery supplied 4.6 kWh");
  });

  it("at 18:00 exactly, still says when the window starts", () => {
    const day = makeDay({ ...BEFORE_EVENING, readUntilMs: at(18), eveningDischargeKwh: 0, housesEveningKwh: null });
    expect(hint(day, "houses-evening")).toBe("From 18:00");
    expect(tile(day, "battery-evening")).toMatchObject({ value: { t: "empty" }, hint: "From 18:00" });
  });

  it("before 18:00 today, says when the window starts instead of the battery's zero", () => {
    const day = makeDay({ readUntilMs: at(17, 45), eveningDischargeKwh: 0, housesEveningKwh: null });
    expect(text(day, "houses-evening")).toBe("—");
    expect(hint(day, "houses-evening")).toBe("From 18:00");
    expect(tile(day, "battery-evening")).toMatchObject({ value: { t: "empty" }, hint: "From 18:00" });
    const noMeters = makeDay({ ...day, sources: { ...makeDay().sources, houses: false } });
    expect(hint(noMeters, "houses-evening")).toBe("Needs household meters · From 18:00");
  });

  it("says no battery is registered, or that it gave no readings, rather than a zero", () => {
    const none = makeDay({ sources: { ...makeDay().sources, battery: false }, eveningDischargeKwh: null });
    expect(text(none, "houses-evening")).toBe("3.2 kWh");
    expect(hint(none, "houses-evening")).toBe("No battery registered");
    expect(tile(none, "battery-evening")).toMatchObject({ value: { t: "empty" }, hint: "No battery registered" });
    const unread = makeDay({ eveningDischargeKwh: null });
    expect(hint(unread, "houses-evening")).toBe("No battery readings");
    expect(tile(unread, "battery-evening")).toMatchObject({ value: { t: "empty" }, hint: "No battery readings" });
  });

  it("shows a battery that was read and only charged as having supplied 0 kWh", () => {
    expect(hint(makeDay({ eveningDischargeKwh: 0 }), "houses-evening")).toBe("Battery supplied 0.0 kWh");
    expect(text(makeDay({ eveningDischargeKwh: 0 }), "battery-evening")).toBe("0.0 kWh");
  });

  it("gives an empty solar figure, never zero, with why", () => {
    expect(tile(makeDay({ solarKwh: null }), "solar")).toMatchObject({ value: { t: "empty", text: "—" }, hint: "No solar meter readings" });
    const noPv = makeDay({ solarKwh: null, sources: { ...makeDay().sources, pv: false } });
    expect(hint(noPv, "solar")).toBe("No complete inverter, grid and battery readings");
  });

  it("marks solar as derived only when it is the balance at the inverter", () => {
    const estimated = tile(makeDay({ solarEstimated: true }), "solar");
    expect(estimated.hint).toBe("≈ inverter output − grid − battery");
    expect(estimated.value.derived).toBe(true);
    expect(tile(makeDay(), "solar").value.derived).toBeUndefined();
  });

  it("splits power cuts into a count and a duration, with a status only when there were cuts", () => {
    expect(tile(makeDay(), "cuts")).toMatchObject({
      value: { t: "number", v: 2, text: "2" },
      hint: "Cuts / time without grid power",
      status: { t: "status", v: "cut", tone: "warning", text: "Grid cuts" },
    });
    expect(tile(makeDay(), "cut-time").value).toMatchObject({ t: "number", v: 250, unit: "min", text: "4h 10m" });
    const none = makeDay({ cuts: [], cutMinutes: 0 });
    expect([text(none, "cuts"), text(none, "cut-time")]).toEqual(["0", "0m"]);
    expect(tile(none, "cuts").status).toBeUndefined();
  });

  it("gives the lowest battery level, its time and whether it was in a cut", () => {
    expect(text(makeDay(), "lowest-soc")).toBe("12%");
    expect(hint(makeDay(), "lowest-soc")).toBe("At 05:30, in a cut");
    const outside = makeDay({ lowestSoc: { pct: 40, atMs: at(7, 15), duringCut: false } });
    expect([text(outside, "lowest-soc"), hint(outside, "lowest-soc")]).toEqual(["40%", "At 07:15"]);
  });

  it("sets the floor status at or below the battery's floor, not above it", () => {
    const status = (pct: number) => tile(makeDay({ lowestSoc: { pct, atMs: at(7, 15), duringCut: false } }), "lowest-soc").status;
    expect(status(15)).toMatchObject({ v: "floor", tone: "warning", text: "At the floor" });
    expect(status(15.5)).toBeUndefined();
  });

  it("gives the battery level at 17:00", () => {
    expect(tile(makeDay(), "soc-17")).toMatchObject({ label: "Battery at 17:00", value: { text: "64%" }, hint: "Before the evening window" });
  });

  it("gives lights on with one decimal, the dark time, and a status when dark", () => {
    expect(text(makeDay(), "lights-on")).toBe("95.8%");
    expect(hint(makeDay(), "lights-on")).toBe("Dark 1h 0m");
    expect(tile(makeDay(), "lights-on").status).toMatchObject({ v: "dark", tone: "danger", text: "Houses dark" });
    const clear = makeDay({ dark: [], darkMinutes: 0, lightsOnPct: 100 });
    expect([text(clear, "lights-on"), hint(clear, "lights-on")]).toEqual(["100.0%", "No dark time"]);
    expect(tile(clear, "lights-on").status).toBeUndefined();
  });

  it("says how much dark time was inferred and how long there was no data", () => {
    expect(hint(makeDay({ darkMinutes: 250, darkInferredMinutes: 30, noDataMinutes: 15 }), "lights-on")).toBe(
      "Dark 4h 10m (30m inferred from a low battery) · No data 15m",
    );
    expect(hint(makeDay({ noDataMinutes: 15 }), "lights-on")).toBe("Dark 1h 0m · No data 15m");
    expect(hint(makeDay({ dark: [], darkMinutes: 0, noDataMinutes: 45, lightsOnPct: 100 }), "lights-on")).toBe(
      "No dark time · No data 45m",
    );
  });

  it("gives an empty figure and what is needed for every null value", () => {
    const day = makeDay(NULL_DAY);
    for (const key of ["solar", "houses-evening", "battery-evening", "cuts", "cut-time", "lowest-soc", "soc-17", "lights-on"]) {
      expect(tile(day, key).value, key).toEqual({ t: "empty", text: "—" });
    }
    expect(hint(day, "solar")).toBe("Needs a solar meter, or an inverter output meter with the battery and grid meter");
    expect(hint(day, "cuts")).toBe("Needs a grid meter");
    expect(hint(day, "houses-evening")).toBe("Needs household meters · No battery registered");
    expect(hint(day, "lowest-soc")).toBe("Needs a battery");
    expect(hint(day, "soc-17")).toBe("No reading at 17:00");
  });

  it("leaves out the battery series, and says why, when no battery is registered", () => {
    expect(build(makeDay(NULL_DAY)).body.series).toBeUndefined();
    expect(ext(makeDay(NULL_DAY)).chartEmpty).toBe("No battery is registered on this microgrid.");
    expect(ext(makeDay()).chartEmpty).toBeNull();
  });

  it("keeps a missing bin as a null point, which breaks the line", () => {
    const [series] = build(makeDay()).body.series!;
    expect(series).toMatchObject({ key: "soc", label: "Battery level", unit: "%" });
    expect(series.points).toEqual(makeDay().soc.map((p) => [new Date(p.atMs).toISOString(), p.pct]));
  });

  it("heads a complete day with its date and zone, and today so far with the time read", () => {
    expect(build(makeDay()).subtitle).toBe("Thu, 05 Nov 2026 · Africa/Kampala");
    const today = build(makeDay(BEFORE_EVENING), "2026-11-05");
    expect(today.subtitle).toBe("Today so far, up to 14:15 · Africa/Kampala");
    expect(today.body.tiles.find((t) => t.key === "evening-supply")!.value).toEqual({
      t: "text",
      text: "The evening window has not started yet.",
    });
    expect((today.ext!.data as { eveningEmpty: string }).eveningEmpty).toBe("The evening window has not started yet.");
  });

  it("notes missing data that was not counted as dark, only when there was some", () => {
    expect(ext(makeDay({ noDataMinutes: 30 })).notes[0]).toBe(
      "No data for 30m (gateway or connection down while the grid was on and the battery above 15%, or not yet known); that time is not counted as dark.",
    );
    expect(ext(makeDay()).notes).toHaveLength(1);
  });

  it("defines cuts, inferred dark time and lights on in the footnote, naming the zone", () => {
    const footnote = ext(makeDay({ resolutionMinutes: 5 })).notes.at(-1);
    expect(footnote).toContain("A power cut is any grid phase below 170 V over a 5-minute reading.");
    expect(footnote).toContain(
      "When it went silent with the battery at or below 15%, the houses are taken to be dark and the grid off, since the gateway cannot outlive the battery; that time is shown as inferred.",
    );
    expect(footnote).toContain("Lights on is the share of the day that was not dark, leaving out time with no data.");
    expect(footnote).toContain("Times are Africa/Kampala.");
  });

  it("labels the evening tiles from the evening start, with an en dash", () => {
    const labels = build(makeDay()).body.tiles.map((t) => t.label);
    expect(labels).toContain("Houses used 18:00–24:00");
    expect(labels).toContain("Battery supplied 18:00–24:00");
    expect(labels).toContain("Who served the houses, 18:00–24:00");
  });

  it("describes the battery chart, ending at 24:00 or at the time read", () => {
    const label = ext(makeDay()).chartLabel;
    expect(label).toBe("Battery level from 00:00 to 24:00. Lowest 12% at 05:30. 2 power cuts. Houses dark for 1h 0m.");
    expect(ext(makeDay(BEFORE_EVENING)).chartLabel).toContain("from 00:00 to 14:15.");
  });

  it("describes who served the houses, listing No data only when there was some", () => {
    expect(ext(makeDay()).eveningLabel).toBe("Battery 3.0 h, Battery + grid 1.0 h, Grid alone 1.0 h, Dark 1.0 h");
    expect(text(makeDay(), "evening-supply")).toBe("Battery 3.0 h · Battery + grid 1.0 h · Grid alone 1.0 h · Dark 1.0 h");
    const gap = makeDay({
      evening: [
        { startMs: at(18), endMs: at(23), supply: "battery" },
        { startMs: at(23), endMs: at(24), supply: "no_data" },
      ],
      eveningHours: { battery: 5, battery_and_grid: 0, grid: 0, dark: 0, no_data: 1 },
    });
    expect(text(gap, "evening-supply")).toContain("No data 1.0 h");
    expect(ext(gap).evening[1]).toMatchObject({ supply: "no_data", label: "No data, 23:00–00:00" });
  });

  it("links the previous day always, the next day before today and today on other days", () => {
    const ids = (date: string) =>
      buildSiteDayModel(makeDay({ date }), { microgrid: MG, today: "2026-11-06", locale: LOCALE, fmt }).links!.map((l) => [l.id, l.href]);
    expect(ids("2026-11-05")).toEqual([
      ["metering.day-previous", `${OPS}?date=2026-11-04`],
      ["metering.day-next", `${OPS}?date=2026-11-06`],
      ["metering.day-today", `${OPS}?date=2026-11-06`],
    ]);
    expect(ids("2026-11-06")).toEqual([["metering.day-previous", `${OPS}?date=2026-11-05`]]);
  });

  it("marks every Value synthetic, and the ext, for a synthetic day only", () => {
    const model = build(makeDay({ synthetic: true }));
    for (const t of model.body.tiles) {
      expect(t.value.synthetic, t.key).toBe(true);
      if (t.status) expect(t.status.synthetic).toBe(true);
    }
    expect((model.ext!.data as { synthetic: boolean }).synthetic).toBe(true);
    expect(JSON.stringify(build(makeDay()))).not.toContain("synthetic\":true");
  });

  it("emits only declared keys", () => {
    for (const day of [makeDay(), makeDay(NULL_DAY), makeDay(BEFORE_EVENING)]) {
      const m = build(day);
      for (const key of [...m.body.tiles.map((t) => t.key), ...(m.body.series ?? []).map((s) => s.key)]) {
        expect(SITE_DAY_KEYS).toContain(key);
      }
    }
  });
});

describe("buildNoSiteDevicesModel", () => {
  const model = buildNoSiteDevicesModel({
    microgrid: MG, date: "2026-11-05", today: "2026-11-06", timezone: "Africa/Kampala", locale: LOCALE, fmt,
  });
  it("says what to register and links to Edges and the other days", () => {
    expect(model.body.tiles).toEqual([
      { key: "setup", label: "Register the battery and grid meter", value: { t: "text", text: expect.stringContaining("Discover them on the microgrid's edge") } },
    ]);
    expect(model.links![0]).toEqual({ id: "metering.edges", label: "Go to Edges", href: `/microgrids/${MG.id}/setup/edges` });
    expect(model.links!.map((l) => l.id)).toEqual(["metering.edges", "metering.day-previous", "metering.day-next", "metering.day-today"]);
    expect(model.ext!.data).toEqual({
      state: "no-site-devices",
      date: "2026-11-05",
      today: "2026-11-06",
      timezone: "Africa/Kampala",
      dayHref: OPS,
      synthetic: false,
      title: "Register the battery and grid meter",
      message: expect.stringContaining("Discover them on the microgrid's edge"),
    });
  });

  it("heads the day with its date and zone, and names the microgrid", () => {
    expect(model.subtitle).toBe("Thu, 05 Nov 2026 · Africa/Kampala");
    expect(model.entity).toEqual({ kind: "microgrid", id: MG.id, label: MG.name });
  });
});

// ── The ext's chart and strip data ──────────────────────────────────────────

describe("the ext a renderer draws the chart and the strip from", () => {
  const iso = (ms: number) => new Date(ms).toISOString();

  it("carries the cut and dark bands, a band ending at the day's end labelled 24:00", () => {
    expect(ext(makeDay()).cuts).toEqual([
      { start: iso(at(2)), end: iso(at(4, 30)), label: "02:00–04:30" },
      { start: iso(at(13)), end: iso(at(14, 40)), label: "13:00–14:40" },
    ]);
    expect(ext(makeDay()).dark).toEqual([{ start: iso(at(23)), end: iso(at(24)), label: "23:00–24:00" }]);
    expect(ext(makeDay(NULL_DAY)).cuts).toBeNull();
    expect(ext(makeDay(NULL_DAY)).dark).toEqual([]);
  });

  it("carries the chart's hour marks and the strip's ticks", () => {
    expect(ext(makeDay()).hourMarks).toEqual(
      [0, 3, 6, 9, 12, 15, 18, 21, 24].map((h) => ({ at: iso(at(h)), label: String(h).padStart(2, "0") })),
    );
    expect(ext(makeDay()).eveningTicks).toEqual(
      [18, 19, 20, 21, 22, 23, 24].map((h) => ({ at: iso(at(h)), label: `${h}:00` })),
    );
  });

  it("never places a tick after the day's end on a day whose evening is short", () => {
    // A clock that jumps forward in the evening leaves five hours from 18:00 to midnight.
    const short = makeDay({ dayEndMs: at(23), readUntilMs: at(23), evening: [], dark: [] });
    const ticks = ext(short).eveningTicks as { at: string; label: string }[];
    expect(ticks.map((t) => t.label)).toEqual(["18:00", "19:00", "20:00", "21:00", "22:00", "23:00", "24:00"]);
    expect(ticks.at(-1)!.at).toBe(iso(at(23)));
    expect(ticks.at(-2)!.at).toBe(iso(at(23)));
    for (const t of ticks) expect(Date.parse(t.at)).toBeLessThanOrEqual(at(23));
  });

  it("says whether the day is partial, which sources it read and the evening's hours", () => {
    expect(ext(makeDay()).partial).toBe(false);
    expect(ext(makeDay(BEFORE_EVENING)).partial).toBe(true);
    expect(ext(makeDay({ sources: { ...makeDay().sources, battery: false } })).sources).toEqual({
      battery: false, gridMeter: true, load: true, pv: true, houses: true,
    });
    expect(ext(makeDay({ sources: { ...makeDay().sources, pv: false, houses: false } })).sources).toEqual({
      battery: true, gridMeter: true, load: true, pv: false, houses: false,
    });
    expect(ext(makeDay()).eveningHours).toEqual(makeDay().eveningHours);
  });

  it("names the microgrid", () => {
    expect(build(makeDay()).entity).toEqual({ kind: "microgrid", id: MG.id, label: MG.name });
  });

  it("percent-encodes the microgrid id in every link it builds", () => {
    const odd = { id: "a b?c", name: "Odd" };
    const day = buildSiteDayModel(makeDay(), { microgrid: odd, today: "2026-11-06", locale: LOCALE, fmt });
    const none = buildNoSiteDevicesModel({ microgrid: odd, date: "2026-11-05", today: "2026-11-06", timezone: "UTC", locale: LOCALE, fmt });
    const ops = "/microgrids/a%20b%3Fc/operations";
    for (const link of [...day.links!, ...none.links!.slice(1)]) expect(link.href.startsWith(`${ops}?date=`), link.id).toBe(true);
    expect(none.links![0].href).toBe("/microgrids/a%20b%3Fc/setup/edges");
    expect((day.ext!.data as { dayHref: string }).dayHref).toBe(ops);
    expect((none.ext!.data as { dayHref: string }).dayHref).toBe(ops);
  });
});

// ── Parity with the legacy component ────────────────────────────────────────

/** Days computed from the fixture generator, one per scenario, plus a partial today and a grid meter only. */
function generatedDays(): SiteDayOperations[] {
  const edge = "SYNTHETIC-EDGE-001";
  const device = (id: string) => ({ id, edgeOpenemsId: edge, componentId: `meter-${id}` });
  const full: SiteSources = {
    battery: device("battery"), gridMeter: device("grid"), load: device("load"), pv: null,
    houseMeters: [device("house-a"), device("house-b")], houseMetersUnreadable: 0,
  };
  const gridOnly: SiteSources = { ...full, battery: null, load: null, houseMeters: [] };
  const day = (date: string, sources: SiteSources, nowMs = Date.parse("2030-01-01T00:00:00Z")) =>
    computeSiteDay({
      date,
      timezone: "Africa/Kampala",
      samples: generateSiteSamples({
        microgridId: MG.id, sources, startDate: addDaysToDateKey(date, -1), endDate: date, timezone: "Africa/Kampala", resolutionMinutes: 5,
      }),
      sources: {
        battery: !!sources.battery, gridMeter: !!sources.gridMeter, load: !!sources.load, pv: !!sources.pv,
        houses: sources.houseMeters.length > 0, houseMetersUnreadable: 0,
      },
      resolutionMinutes: 5,
      nowMs,
    });
  const found = new Map<SiteScenario, string>();
  for (let i = 0; found.size < 5 && i < 365; i++) {
    const date = addDaysToDateKey("2026-01-01", i);
    const s = siteScenario(SITE_FIXTURE_SEED, MG.id, date);
    if (!found.has(s)) found.set(s, date);
  }
  return [
    ...[...found.values()].map((date) => ({ ...day(date, full), synthetic: true as const })),
    day("2026-06-10", full, Date.parse("2026-06-10T11:00:00Z")),
    day("2026-06-10", gridOnly),
  ];
}

/** Each legacy tile's label, value and detail, as the page shows them. */
function legacyTiles(day: SiteDayOperations): Record<string, [string, string]> {
  const root = document.createElement("div");
  root.innerHTML = renderToStaticMarkup(<DailyOperations day={day} />);
  const out: Record<string, [string, string]> = {};
  for (const section of root.querySelectorAll("section")) {
    const [label, value, detail] = Array.from(section.querySelectorAll(":scope > p")).map((p) => p.textContent ?? "");
    if (value !== undefined) out[label] = [value, detail ?? ""];
  }
  return out;
}

describe("parity with the Operations page", () => {
  const DAYS = [
    makeDay(), makeDay(NULL_DAY), makeDay(BEFORE_EVENING), makeDay({ solarEstimated: true, noDataMinutes: 30, darkInferredMinutes: 20 }),
    makeDay({ housesEveningMetersMissing: 2, eveningDischargeKwh: null }),
    makeDay({ ...BEFORE_EVENING, readUntilMs: at(18), eveningDischargeKwh: 0, housesEveningKwh: null }), ...generatedDays(),
  ];

  it.each(DAYS.map((day, i) => [i, day] as const))("day %i: the tiles read as the page's", (_i, day) => {
    const model = build(day);
    const t = Object.fromEntries(model.body.tiles.map((x) => [x.key, x]));
    const cuts = t.cuts.value.t === "empty" ? "—" : `${t.cuts.value.text} / ${t["cut-time"].value.text}`;
    const legacy = legacyTiles(day);
    const pairs: [string, string, string | undefined][] = [
      ["solar", t.solar.value.text, t.solar.hint],
      ["houses-evening", t["houses-evening"].value.text, t["houses-evening"].hint],
      ["cuts", cuts, t.cuts.hint],
      ["lowest-soc", t["lowest-soc"].value.text, t["lowest-soc"].hint],
      ["soc-17", t["soc-17"].value.text, t["soc-17"].hint],
      ["lights-on", t["lights-on"].value.text, t["lights-on"].hint],
    ];
    for (const [key, value, detail] of pairs) expect(legacy[t[key].label], key).toEqual([value, detail]);
  });

  it.each(DAYS.map((day, i) => [i, day] as const))("day %i: the notes and descriptions read as the page's", (_i, day) => {
    const html = renderToStaticMarkup(<DailyOperations day={day} />);
    const root = document.createElement("div");
    root.innerHTML = html;
    const data = build(day).ext!.data as { chartLabel: string; eveningLabel: string; notes: string[]; evening: { label: string }[] };
    const page = root.textContent ?? "";
    for (const note of data.notes) expect(page).toContain(note);
    if (day.sources.battery) expect(root.querySelector("svg")!.getAttribute("aria-label")).toBe(data.chartLabel);
    const strip = Array.from(root.querySelectorAll('div[role="img"]'))[0];
    if (strip) {
      expect(strip.getAttribute("aria-label")).toBe(data.eveningLabel);
      expect(Array.from(strip.children).map((c) => c.getAttribute("title"))).toEqual(data.evening.map((e) => e.label));
    }
    if (day.readUntilMs < day.dayEndMs) expect(page).toContain(`${build(day).subtitle!.split(" · ")[0]}.`);
  });
});

// ── The strict parse ────────────────────────────────────────────────────────

const VIEW = {
  id: "metering.site-day",
  kind: "metrics",
  path: "/microgrids/[id]/operations",
  params: { id: "microgrid" },
  entity: "id",
  cost: "vendor",
  declares: { keys: SITE_DAY_KEYS },
  ext: { schema: SITE_DAY_EXT_SCHEMA, zod: SiteDayExt },
  examples: [],
  load: async () => ({ ok: false, status: 503, message: "not loaded here" }),
} as const satisfies ViewDef;

describe("the metering.site-day@1 ext", () => {
  it("is strict at every depth", () => {
    expect(strictProblems(SiteDayExt)).toEqual([]);
  });

  it("parses every model with the view's strict parse", () => {
    const models = [
      ...[makeDay(), makeDay(NULL_DAY), makeDay(BEFORE_EVENING), makeDay({ synthetic: true })].map((d) => build(d)),
      ...generatedDays().map((d) => build(d)),
      buildNoSiteDevicesModel({ microgrid: MG, date: "2026-11-05", today: "2026-11-06", timezone: "UTC", locale: LOCALE, fmt }),
    ];
    for (const m of models) expect(strictParseModel(VIEW, m)).toMatchObject({ ok: true });
  });

  it("refuses an unknown key at any depth, and an off-site day link", () => {
    const data = build(makeDay()).ext!.data as Record<string, unknown>;
    const refuses = (d: unknown) => expect(SiteDayExt.safeParse(d).success).toBe(false);
    refuses({ ...data, extra: 1 });
    refuses({ ...data, sources: { ...(data.sources as object), solar: true } });
    refuses({ ...data, cuts: [{ start: data.dayStart, end: data.dayEnd, label: "x", colour: "red" }] });
    refuses({ ...data, dayHref: "//elsewhere.example/x" });
    refuses({ ...data, state: "other" });
    expect(SiteDayExt.safeParse(data).success).toBe(true);
  });

  it("refuses values outside its bounds: a non-instant time, too many bands or notes, a long note, negative hours", () => {
    const data = build(makeDay()).ext!.data as Record<string, unknown> & { cuts: unknown[]; eveningHours: object };
    const refuses = (d: unknown) => expect(SiteDayExt.safeParse(d).success).toBe(false);
    refuses({ ...data, dayStart: "yesterday" });
    refuses({ ...data, cuts: Array(289).fill(data.cuts[0]) });
    expect(SiteDayExt.safeParse({ ...data, cuts: Array(288).fill(data.cuts[0]) }).success).toBe(true);
    refuses({ ...data, notes: Array(5).fill("x") });
    refuses({ ...data, notes: ["x".repeat(801)] });
    refuses({ ...data, eveningHours: { ...data.eveningHours, battery: -1 } });
    refuses({ ...data, eveningHours: { ...data.eveningHours, battery: 26 } });
  });
});
